// 03 階段（1段か3段）
const stairs = (n: number): E[] => Array.from({ length: n }, (_, i) => bx(20 + i * 34, 112 - (i + 1) * 9, 34, (i + 1) * 9, undefined, C.gray, FILL.gray));
const vals03 = [1, 1, 1, 2, 3, 4, 6, 9, 13];
const cell03 = (i: number, col: string, fill: string): E => ci(28 + i * 33, 72, 14, String(vals03[i]), col, fill, 12);
const lab03 = (): E[] => vals03.map((_, i) => tx(28 + i * 33, 108, String(i), 11, C.gray));
const a03: Figure = show([
  S('1回に1段か3段だけ上がれる階段を、8段上がります。上がり方は何通りあるか数えます。', ['8段の上がり方は？'], [...stairs(8), tx(160, 32, '1段 または 3段ずつ', 14, C.ink)]),
  SF('8段目に着く最後の1回は、2通りだけです。7段目から1段上がるか、5段目から3段上がるか。', ['最後の1回は2通り', '7段目から1段　5段目から3段'], [bl(20, 40, 130, 44, '7段目から\n1段', 14), bl(170, 40, 130, 44, '5段目から\n3段', 14), tx(160, 112, 'どちらも8段目に着く', 13, C.purple)]),
  SF('この2つは別々の上がり方で、もれも重なりもありません。だから、8段目＝7段目＋5段目と足し算で求められます。', ['n段目＝(n−1)段目＋(n−3)段目'], [pu(30, 40, 260, 44, 'n段目＝(n−1)段目＋(n−3)段目', 15), tx(160, 112, '8段目＝7段目＋5段目', 14, C.red)]),
  SF('表を作ります。地面（0段目）は1通り。1段目は1通り、2段目は1＋1の1通りです。', ['0段目＝1　1段目＝1　2段目＝1'], [...lab03(), cell03(0, C.green, FILL.green), cell03(1, C.green, FILL.green), cell03(2, C.green, FILL.green)]),
  S('3段目＝2段目＋0段目＝1＋1＝2通り。4段目＝3段目＋1段目＝2＋1＝3通り。5段目＝4段目＋2段目＝3＋1＝4通りです。', ['3段目＝1＋1＝2', '4段目＝2＋1＝3　5段目＝3＋1＝4'], [cell03(3, C.blue, FILL.blue), cell03(4, C.blue, FILL.blue), cell03(5, C.blue, FILL.blue)]),
  S('6段目＝5段目＋3段目＝4＋2＝6通り。7段目＝6段目＋4段目＝6＋3＝9通りです。', ['6段目＝4＋2＝6', '7段目＝6＋3＝9'], [cell03(6, C.blue, FILL.blue), cell03(7, C.blue, FILL.blue)]),
  S('8段目＝7段目＋5段目＝9＋4＝13通りです。', ['8段目＝9＋4＝13通り'], [cell03(8, C.red, FILL.red)]),
  S('答えは13通りです。', ['=答え　13通り']),
  SF('確かめ。3段を使う回数で分けます。0回は1通り。1回は、全部で6回の動きのうち3段がどこに来るかで6通り。2回は、4回の動きのうち3段2回の位置の選び方で6通り。', ['0回:1通り　1回:6通り　2回:6通り', '=1＋6＋6＝13通り ✓'], [gn(14, 36, 90, 40, '3段0回\n1通り', 13), gn(115, 36, 90, 40, '3段1回\n6通り', 13), gn(216, 36, 90, 40, '3段2回\n6通り', 13), tx(160, 112, '足して 13通り', 14, C.purple)]),
], '最後の1回で場合分け。n段目＝(n−1)段目＋(n−3)段目。8段で13通り。');

// 04 論理（宝の箱）
const T4 = { x0: 64, w: 44, y0: 38, h: 20 };
const head04 = (): E[] => [tx(36, 30, '箱', 11, C.gray), ...['ア', 'イ', 'ウ', 'エ'].map((t, i) => tx(T4.x0 + i * T4.w + 20, 30, t, 12, C.ink)), tx(272, 30, '本当の人数', 11, C.gray), ...['A', 'B', 'C', 'D', 'E'].map((t, i) => tx(36, T4.y0 + i * T4.h + 15, t, 13, C.ink))];
