const cube11 = (hole: boolean): E[] => {
  const out: E[] = [];
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) {
    const mid = i === 1 && j === 1;
    if (mid && hole) out.push(bx(100 + j * 40, 28 + i * 34, 38, 32, undefined, C.red, '#FFFFFF'));
    else out.push(bx(100 + j * 40, 28 + i * 34, 38, 32, undefined, C.ink, FILL.gray));
  }
  return out;
};
